<?php use Luna\Core\View; ?>
<section class="card" id="assets">
    <div class="card-header"><div><span class="section-kicker">Registro beni ammortizzabili</span><h2>Cespiti: valori civilistici e fiscali</h2></div></div>
    <div class="content-grid embedded-grid">
        <div class="span-5"><form method="post" action="/accounting/compliance/asset-categories" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="year" value="<?= $year ?>"><div class="form-section-head"><h2>Nuova categoria</h2></div><div class="form-grid single-card-form"><label class="field"><span>Codice</span><input name="code" required></label><label class="field"><span>Nome</span><input name="name" required></label><label class="field"><span>Aliquota civilistica %</span><input name="civil_rate" required></label><label class="field"><span>Aliquota fiscale %</span><input name="tax_rate" required></label><label class="field"><span>Primo anno %</span><input name="first_year_percent" value="50"></label><input type="hidden" name="active" value="1"></div><div class="form-actions"><button class="button" type="submit">Aggiungi categoria</button></div></form></div>
        <div class="span-7"><form method="post" action="/accounting/compliance/assets" class="modern-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="year" value="<?= $year ?>"><div class="form-section-head"><h2>Nuovo cespite</h2><p class="help">Collega la fattura quando disponibile: fornitore, numero e data vengono acquisiti automaticamente.</p></div><div class="form-grid">
            <label class="field"><span>Codice *</span><input name="asset_code" required></label><label class="field"><span>Descrizione *</span><input name="description" required></label>
            <label class="field"><span>Categoria *</span><select name="category_id" required><option value="">Seleziona categoria…</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>"><?= View::e($category['code'] . ' · ' . $category['name']) ?></option><?php endforeach; ?></select></label>
            <label class="field"><span>Fattura di acquisto</span><select name="document_id"><option value="">Inserimento manuale</option><?php foreach ($purchaseDocuments as $document): ?><option value="<?= (int) $document['id'] ?>"><?= View::e(View::date($document['document_date']) . ' · ' . $document['number'] . ' · ' . $document['counterparty_name']) ?></option><?php endforeach; ?></select></label>
            <label class="field"><span>Fornitore</span><select name="supplier_id"><option value="">Seleziona…</option><?php foreach ($suppliers as $supplier): ?><option value="<?= (int) $supplier['id'] ?>"><?= View::e($supplier['code'] . ' · ' . $supplier['business_name']) ?></option><?php endforeach; ?></select></label>
            <label class="field"><span>Numero fattura (se manuale)</span><input name="purchase_document_number"></label><label class="field"><span>Data fattura (se manuale)</span><input type="date" name="purchase_document_date"></label><label class="field"><span>Condizione acquisto</span><select name="acquisition_condition"><option value="NEW">Nuovo</option><option value="USED">Usato</option></select></label>
            <label class="field"><span>Data acquisto *</span><input type="date" name="purchase_date" required></label><label class="field"><span>Entrata in funzione</span><input type="date" name="in_service_date"></label><label class="field"><span>Costo storico *</span><input name="purchase_cost" required></label><label class="field"><span>Valore residuo</span><input name="residual_value" value="0"></label><input type="hidden" name="status" value="ACTIVE">
        </div><div class="form-actions"><button class="button primary" type="submit">Registra cespite</button></div></form></div>
    </div>
    <div class="table-wrap"><table><thead><tr><th>Codice</th><th>Cespite</th><th>Categoria</th><th>Documento acquisto</th><th>Condizione</th><th>Costo</th><th>Netto civile</th><th>Netto fiscale</th><th>Stato</th><th>Azioni</th></tr></thead><tbody><?php foreach ($assets as $asset): ?><tr><td><?= View::e($asset['asset_code']) ?></td><td class="primary-cell"><?= View::e($asset['description']) ?></td><td><?= View::e($asset['category_code'] ?? '—') ?></td><td><?= View::e($asset['purchase_document_number'] ?: '—') ?><small class="cell-subtitle"><?= View::e($asset['supplier_name'] ?: '') ?><?= $asset['purchase_document_date'] ? ' · ' . View::date($asset['purchase_document_date']) : '' ?></small></td><td><?= ($asset['acquisition_condition'] ?? 'NEW') === 'USED' ? 'Usato' : 'Nuovo' ?></td><td><?= View::money($asset['purchase_cost']) ?></td><td><?= View::money($asset['net_book_value']) ?></td><td><?= View::money($asset['tax_net_value']) ?></td><td><?= View::e(View::label($asset['status'])) ?></td><td><?php if ($asset['status'] === 'ACTIVE'): ?><form method="post" action="/accounting/compliance/assets/<?= (int) $asset['id'] ?>/calculate" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="year" value="<?= $year ?>"><button class="table-action" type="submit">Calcola <?= $year ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
    <div class="table-wrap"><table><thead><tr><th>Cespite</th><th>Esercizio</th><th>Quota civile</th><th>Quota fiscale</th><th>Stato</th><th></th></tr></thead><tbody><?php foreach ($depreciations as $row): ?><tr><td><?= View::e($row['asset_code'] . ' · ' . $row['description']) ?></td><td><?= (int) $row['fiscal_year'] ?></td><td><?= View::money($row['civil_amount']) ?></td><td><?= View::money($row['tax_amount']) ?></td><td><?= View::e(View::label($row['status'])) ?></td><td><?php if ($row['status'] === 'DRAFT'): ?><form method="post" action="/accounting/compliance/depreciations/<?= (int) $row['id'] ?>/post"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="year" value="<?= $year ?>"><button class="table-action" type="submit">Contabilizza</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
</section>
